import pathlib,json,hashlib,importlib.util,collections,numpy as np
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
SRC=R/'y06_r3_bear_retest_research_v2.py';prior=R/'Y06_R11_FLOW_BARRIER_RESULTS_20261127.json'
sp=importlib.util.spec_from_file_location('r3',SRC);r3=importlib.util.module_from_spec(sp);sp.loader.exec_module(r3)
bt=r3.bt;H=bt.H;M=bt.M
P=R/'Y06_R13_H24_ABSORPTION_V2_PROTOCOL_20261127.json';O=R/'Y06_R13_H24_ABSORPTION_V2_RESULTS_20261127.json'
assert not P.exists() and not O.exists()
p={'status':'RESEARCH_ONLY','parent_sha256':hashlib.sha256(prior.read_bytes()).hexdigest(),'entry':'R11 original FLOW_ABSORB, unchanged selected SHORT intentions. All side control and 48h reference. Fixed entry variants: original; next closed M15 or H1 within 3h confirms lower close and bearish candle vs origin entry; veto if BTC 3h return positive; veto if asset 3h drop greater than 2ATR; combinations. Confirmation uses completed candles and next open, never eventual loss.','exit':'STOP8 plus fixed H24/H48, TP8 H24, conditional H48 extension after H24 if realized mark profit >0.3% and previous 6h declining. H24 stop priority, gap adverse, gross .30 2 slots cooldown original, 10/30bps no funding.','diagnostic':'Original H24 and H48 admitted trades, MFE/MAE excluding stop-trigger candle, loss buckets no fee-sized favorable move, positive excursion >=0.3% then loss, early adverse >=1% at 3h. Entry features BTC3/24/72, asset3/24, ATR stretch. No fitting. All inspected historical splits.'}
P.write_text(json.dumps(p,indent=2),encoding='utf8')
sig=json.loads(prior.read_text())['selected']['FLOW_ABSORB'];btc,_=bt.data('BTC','1h');hs={};ms={};qa={}
for sym in bt.SYMS[1:]:
 h,_=bt.data(sym,'1h');m,_=bt.data(sym,'5m');hs[sym]=h;ms[sym]=m;qa[sym]=r3.prepare_qa(h,m)[0]
 print('LOAD',sym,flush=True)
def endof(per):return bt.PERIODS[per][1] if per!='FORWARD_INSPECTED' else bt.T('2026-11-26T00:00:00Z')
def features(x):
 i=(x['entryTs']-bt.HS)//H;h=hs[x['symbol']]
 a=r3.calc_atr(h,i)
 if a is None or not np.isfinite(h[i-25:i,:4]).all() or not np.isfinite(btc[i-73:i,3]).all():return None
 ret=lambda h,n:float(h[i-1,3]/h[i-1-n,3]-1)
 return {'btc3':ret(btc,3),'btc24':ret(btc,24),'btc72':ret(btc,72),'asset3':ret(h,3),'asset24':ret(h,24),'stretch':float((h[i-4,3]-h[i-1,3])/a)}
def confirm(x,step):
 m=ms[x['symbol']];k=(x['entryTs']-bt.MS)//M;ep=m[k,0]
 if not np.isfinite(ep):return None
 for j in range(k+step,k+36+1,step):
  if j>=len(m) or not np.isfinite(m[j-step:j,:4]).all():break
  t=bt.MS+j*M
  if t>=bt.PERIODS[x['period']][1]:break
  if m[j-1,3]<ep and m[j-1,3]<m[j-step,0]:return {**x,'entryTs':t,'originTs':x['entryTs']}
 return None
def trade(x,hr,tp=0,extend=False):
 m=ms[x['symbol']];h=hs[x['symbol']];k=(x['entryTs']-bt.MS)//M;side=x['side'];j=k+hr*12
 if x['entryTs']+hr*H>=endof(x['period']) or k<0 or j>=len(m) or not np.isfinite(m[k:j+1,:4]).all():return None
 ep=float(m[k,0]);stop=ep*(1-side*.08);target=ep*(1+side*tp) if tp else None
 def hit(j):
  hi=m[k:j,1];lo=m[k:j,2];sh=np.flatnonzero(lo<=stop if side==1 else hi>=stop);th=np.flatnonzero(hi>=target if side==1 else lo<=target) if tp else []
  return int(sh[0]) if len(sh) else j-k,int(th[0]) if len(th) else j-k
 si,ti=hit(j)
 if extend and si==j-k and ti==j-k:
  t=bt.MS+j*M;i=(t-bt.HS)//H
  if i>=7 and np.isfinite(h[i-7:i,3]).all() and side*(m[j,0]/ep-1)>.003 and side*(h[i-1,3]/h[i-7,3]-1)>0:
   if j+288>=len(m) or t+24*H>=endof(x['period']) or not np.isfinite(m[j:j+289,:4]).all():return None
   j+=288;si,ti=hit(j)
 xp=float(m[j,0]);et=bt.MS+j*M;reason='TIME'+str((j-k)//12)
 if si<=ti and si<j-k:
  q=k+si;xp=float(min(m[q,0],stop) if side==1 else max(m[q,0],stop));et=bt.MS+(q+1)*M;reason='HARD_STOP8'
 elif ti<j-k:xp=float(target);et=bt.MS+(k+ti+1)*M;reason='TARGET'
 return {**x,'entry':ep,'exitPrice':xp,'exitTs':et,'direction':'LONG' if side==1 else 'SHORT','rawReturn':side*(xp/ep-1),'exitReason':reason}
def compact(w):return {k:v for k,v in w.items() if k!='accepted'}
arms=collections.defaultdict(list)
for x in sig:
 f=features(x)
 if f is None:continue
 arms['ALL'].append(x)
 if x['side']!= -1:continue
 arms['SHORT'].append(x)
 if f['btc3']<=0:arms['SHORT_BTC3_VETO'].append(x)
 if f['stretch']<=2:arms['SHORT_STRETCH_VETO'].append(x)
 if f['btc3']<=0 and f['stretch']<=2:arms['SHORT_BOTH_VETO'].append(x)
 for n,step in [('M15',3),('H1',12)]:
  a=confirm(x,step)
  if a:arms['SHORT_CONFIRM_'+n].append(a)
  if a and f['btc3']<=0 and f['stretch']<=2:arms['SHORT_CONFIRM_'+n+'_BOTH'].append(a)
out={};diagnostics={}
for arm,xs in arms.items():
 xs=list({(x['symbol'],x['entryTs']):x for x in xs}.values())
 for ex,hr,tp,ext in [('H24',24,0,False),('H24_TP8',24,.08,False),('H48',48,0,False),('H24_CONDITIONAL_H48',24,0,True)]:
  key=arm+'/'+ex;out[key]={}
  for per in bt.PERIODS:
   a=[x for x in xs if x['period']==per];z=[q for x in a if (q:=trade(x,hr,tp,ext)) is not None]
   w={str(f):bt.wallet(z,per,f,ms) for f in (10,30)}
   if arm=='SHORT' and ex in ('H24','H48'):
    ds=[]
    for tr in w['30']['accepted']:
     m=ms[tr['symbol']];k=(tr['entryTs']-bt.MS)//M;j=(tr['exitTs']-bt.MS)//M;ep=tr['entry'];end=j-1 if 'STOP' in tr['exitReason'] else j;b=m[k:max(k,end),:4]
     mfe=max(0,1-tr['exitPrice']/ep,float(1-b[:,2].min()/ep) if len(b) else 0);mae=max(0,tr['exitPrice']/ep-1,float(b[:,1].max()/ep-1) if len(b) else 0)
     r3h=100*(1-m[k+36,0]/ep-.003) if k+36<j else 100*(tr['rawReturn']-.003)
     ds.append({**tr,'mfe_pct':100*mfe,'mae_pct':100*mae,'net_pct':100*(tr['rawReturn']-.003),'net3h_pct':r3h,'features':features(tr)})
    loss=[x for x in ds if x['net_pct']<=0];win=[x for x in ds if x['net_pct']>0]
    summ={'n':len(ds),'loss':len(loss),'loss_mfe_0p3_or_less':sum(x['mfe_pct']<=.3 for x in loss),'loss_mfe_ge1':sum(x['mfe_pct']>=1 for x in loss),'loss_mfe_ge2':sum(x['mfe_pct']>=2 for x in loss),'loss_3h_net_le_minus1':sum(x['net3h_pct']<=-1 for x in loss),'win_3h_net_le_minus1':sum(x['net3h_pct']<=-1 for x in win),'mean_win':float(np.mean([x['net_pct'] for x in win])) if win else None,'mean_loss':float(np.mean([x['net_pct'] for x in loss])) if loss else None}
    diagnostics.setdefault(ex,{})[per]={'summary':summ,'rows':ds};print('DIAG',ex,per,json.dumps(summ,default=lambda x:x.item()),flush=True)
   out[key][per]={'n_intentions':len(a),'n_priced':len(z),'wallet':{f:compact(v) for f,v in w.items()}}
  print('BT',key,[(round(v['wallet']['30']['terminal_jpy']),round(v['wallet']['30']['max_dd_pct'],2),v['wallet']['30']['n'],v['wallet']['30']['wins'],round(v['wallet']['10']['terminal_jpy'])) for v in out[key].values()],flush=True)
O.write_text(json.dumps({'protocol':p,'protocol_sha256':hashlib.sha256(P.read_bytes()).hexdigest(),'results':out,'diagnostics':diagnostics},indent=2,allow_nan=False,default=lambda x:x.item()),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)
